package org.diy.liferecorder;
import android.content.*;import org.json.*;import java.io.*;
/** One entry point for source-backed speaker labels and local voice samples. */
final class SpeakerActions {
 static void show(AppScreen screen,JSONObject shown,JSONObject unit){if(!unit.has("segment_index")){screen.notice.setText("这段原文没有逐句时间，请先完成逐段转写");return;}screen.startActivity(new Intent(screen,VoiceSegmentActivity.class).putExtra("id",shown.optString("id")).putExtra("segment_index",unit.optInt("segment_index")).putExtra("selection",new JSONObject().toString()));}
 private static void choose(AppScreen screen,JSONObject shown,JSONObject unit,boolean sample){try{OfflinePacks packs=new OfflinePacks(screen);JSONArray all=VoiceProfiles.read(packs);if(all.length()==0){screen.notice.setText("尚未登记说话人，请先新建声纹");return;}String[] names=new String[all.length()];for(int i=0;i<names.length;i++)names[i]=all.getJSONObject(i).optString("name");new LocalDialog(screen).setTitle(sample?"将本句补充给谁？":"这句是谁说的？").setItems(names,(d,n)->{try{JSONObject person=all.getJSONObject(n);String id=person.getString("id"),name=person.getString("name");if(!sample){label(screen,shown,unit,id,name);screen.recreate();return;}new LocalDialog(screen).setTitle("确认本句只有 "+name+" 说话").setMessage("请先回听，选择 3–40 秒清晰单人语音；提取声纹后会标注这一句。").setPositiveButton("确认补充",(dialog,w)->screen.background(()->{JSONObject current=current(screen,shown);JSONObject part=segment(current,unit);OfflineSpeech.supplement(packs,current,part,id);label(screen,shown,unit,id,name);},()->screen.recreate())).setNegativeButton("取消",null).show();}catch(Exception e){screen.notice.setText(e.getMessage());}}).show();}catch(Exception e){screen.notice.setText(e.getMessage());}}
 private static JSONObject current(AppScreen screen,JSONObject shown)throws Exception{JSONObject current=screen.store.audio(shown.getString("id"));if(current.optLong("transcript_revision")!=shown.optLong("transcript_revision")||!current.optString("path").equals(shown.optString("path")))throw new IOException("原文或音频已变化，请刷新后重试");File file=new File(current.getString("path"));String expected=current.optInt("source_retained",1)==0?current.optString("retained_sha"):current.optString("sha");if(!org.diy.lifecore.LocalSecurity.hash(file).equals(expected))throw new IOException("音频校验失败");return current;}
 private static JSONObject segment(JSONObject current,JSONObject unit)throws Exception{JSONArray segments=new JSONObject(current.getString("speech_json")).getJSONArray("segments");int index=unit.getInt("segment_index");if(index<0||index>=segments.length())throw new IOException("这句已变化，请刷新");return segments.getJSONObject(index);}
 static void label(AppScreen screen,JSONObject shown,JSONObject unit,String profileId,String name)throws Exception{label(screen.store,shown,unit,profileId,name);}
 static void label(RecordStore store,JSONObject shown,JSONObject unit,String profileId,String name)throws Exception{if(name.trim().isEmpty()||name.length()>60)throw new IOException("请输入 1–60 字名称");JSONObject current=store.audio(shown.getString("id"));if(current.optLong("transcript_revision")!=shown.optLong("transcript_revision"))throw new IOException("原文已变化，请刷新后重试");JSONObject speech=new JSONObject(current.getString("speech_json"));JSONObject part=speech.getJSONArray("segments").getJSONObject(unit.getInt("segment_index"));part.put("speaker",name.trim()).put("speaker_confirmed",true);if(profileId.isEmpty())part.remove("voice_profile_id");else part.put("voice_profile_id",profileId);store.editSpeech(current.getString("id"),current.optLong("transcript_revision"),speech);}
}
